operations.command:
nixosctl eval config.settings.users.admin.username | tr -d '"' > /var/tmp/e2e-user && nixosctl eval config.settings.disk.by.partlabel.root | tr -d '"' > /var/tmp/e2e-root && test -s /var/tmp/e2e-user && getent shadow "$(cat /var/tmp/e2e-user)" > /dev/null && cat > /var/tmp/e2e-crypt.sh <<'EOF'
crypt() { perl -e 'chomp(my $p = <STDIN>); print crypt($p, $ENV{HASH})'; }
accepts() { HASH=$(getent shadow "$(cat /var/tmp/e2e-user)" | cut -d: -f2); case "$HASH" in '$'*) ;; *) return 1;; esac; export HASH; test "$(printf %s "$1" | crypt)" = "$HASH"; }
fileaccepts() { HASH=$(cat /etc/nixos/secrets/hashed_password.txt); case "$HASH" in '$'*) ;; *) return 1;; esac; export HASH; test "$(printf %s "$1" | crypt)" = "$HASH"; }
nowarning() { ! journalctl -b -q | grep -F 'does not exist' | grep -Fq hashed_password.txt; }
diag() { { u=$(cat /var/tmp/e2e-user); echo "user=[$u]"; getent passwd "$u" | cut -d: -f1-4; echo "shadow-entry=$(getent shadow "$u" | cut -d: -f2 | cut -c1-16)"; echo "shadow-users: $(cut -d: -f1 /etc/shadow | tr '\n' ' ')"; ls -la /etc/shadow; echo "file=$(cut -c1-16 /etc/nixos/secrets/hashed_password.txt)"; findmnt -rn --target /etc/nixos; findmnt -rn --target /var/lib/nixos; readlink /run/current-system; journalctl -b -q --no-pager | grep -iE "update-users|nixos-activation|activate|perl|warning" | tail -12; echo "pam-journal:"; journalctl -b -q --no-pager | grep -iE "passwd|pam_|chauthtok|kwallet|runuser" | tail -20; echo "runuser-id:"; runuser -u "$u" -- id; systemctl --failed --no-pager | head -6; for f in /tmp/e2e-*.log; do [ -f "$f" ] && { echo "== $f"; tail -15 "$f"; }; done; } 2>&1 | sed "s/^/DIAG /"; }
EOF
. /var/tmp/e2e-crypt.sh && accepts testpass123 && fileaccepts testpass123 && nowarning && findmnt -rn --target /etc/nixos | grep -F '@persist/dirs/etc!nixos' && printf boot-hash-ok || { diag; exit 1; }
